class Undefined:
    def __init__(self, name=""):
        self.name = name

    def __getattr__(self, key):
        return Undefined(self.name + "." + key)

    def __getitem__(self, key):
        return Undefined(self.name + "[" + str(key) + "]")

    def __str__(self):
        return ""

    def __repr__(self):
        return ""

    def __bool__(self):
        return False

    def __iter__(self):
        return iter(())


def _lookup(context, name):
    if isinstance(context, dict):
        return context.get(name, Undefined(name))
    return getattr(context, name, Undefined(name))


def _attr(value, name):
    if isinstance(value, dict):
        return value.get(name, Undefined(name))
    if isinstance(value, (list, tuple, str)) and name == "length":
        return len(value)
    try:
        return getattr(value, name)
    except (AttributeError, TypeError):
        return Undefined(name)


def _add(left, right):
    if isinstance(left, str) or isinstance(right, str):
        def text(v):
            if v is None:
                return "none"
            if v is True:
                return "true"
            if v is False:
                return "false"
            return str(v)
        return text(left) + text(right)
    return left + right


def _test(value, name):
    if name == "iterable":
        try:
            iter(value)
            return True
        except TypeError:
            return False
    if name == "sequence":
        return isinstance(value, (list, tuple, str))
    if name in ("mapping", "map"):
        return isinstance(value, dict)
    if name == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if name == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if name == "string":
        return isinstance(value, str)
    if name in ("boolean", "bool"):
        return isinstance(value, bool)
    if name == "odd":
        return isinstance(value, int) and not isinstance(value, bool) and value % 2 != 0
    if name == "even":
        return isinstance(value, int) and not isinstance(value, bool) and value % 2 == 0
    return False


class _Attributes(ast.NodeTransformer):
    def visit_Attribute(self, node):
        self.generic_visit(node)
        return ast.copy_location(ast.Call(
            func=ast.Name(id="_attr", ctx=ast.Load()),
            args=[node.value, ast.Constant(node.attr)], keywords=[]), node)

    def visit_BinOp(self, node):
        self.generic_visit(node)
